mapper.select:
SELECT COUNT(*) FROM shopion.tPrfCustConcrnProd CP INNER JOIN shopion.tPrdProd P ON CP.ProdCode = P.ProdCode INNER JOIN shopion.tPrfCust CI ON CP.CustId = CI.CustId
AND CI.ChnlCode = #{pChnlCode} AND CI.CustName LIKE CONCAT('%',#{pCustName},'%') AND CI.LoginId LIKE CONCAT('%',#{pLoginId},'%') AND CI.CustId = #{pCustId}
AND P.SaleYn = 1

SELECT P.ProdCode, P.ShopProdCode, P.ProdName, P.ProdUnit, P.ImgUrl80, P.AttrValStr1, P.BrandName, P.ModelName, P.SalePrice, P.VatRate, P.MakerName, P.OriginName, P.DeliFeeType, P.DeliFeeAmt, P.SaleYn, P.RegistDate, P.ChangeDate, COUNT(*) AS OrderCount, SUM(OP.ProdQty) AS OrderQty, MAX(O.OrderReciptDate) AS LastOrderDate FROM shopion.tPrdProd P LEFT OUTER JOIN ( SELECT shopion.tStrProdCpn.*, tStrProdCpnProd.ProdCode, tStrProdCpnProd.ChnlCode FROM shopion.tStrProdCpn INNER JOIN shopion.tStrProdCpnProd ON shopion.tStrProdCpnProd.CpnId = shopion.tStrProdCpn.CpnId AND shopion.tStrProdCpnProd.ChnlCode = #{pChnlCode} ) PC ON P.ProdCode = PC.ProdCode LEFT OUTER JOIN ( SELECT shopion.tStrPoint.*, tStrPointProd.ProdCode, tStrPointProd.ChnlCode FROM shopion.tStrPoint INNER JOIN shopion.tStrPointProd ON shopion.tStrPointProd.PointId = shopion.tStrPoint.PointId AND shopion.tStrPointProd.ChnlCode = #{pChnlCode} ) PP ON P.ProdCode = PP.ProdCode
LEFT OUTER JOIN shopion.tOrdOrderProd OP ON OP.ProdCode = P.ProdCode LEFT OUTER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo AND O.CustId = #{pCustId} INNER JOIN shopion.tPrfCustConcrnProd CCP ON CCP.ProdCode = P.ProdCode AND CCP.CustId = #{pCustId}
INNER JOIN shopion.tOrdOrderProd OP ON OP.ProdCode = P.ProdCode INNER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo AND O.CustId = #{pCustId}
WHERE P.SaleYn = 1 AND EXISTS (SELECT ProdCode FROM shopion.tPrdProdChnl WHERE ProdCode = P.ProdCode AND ChnlCode = #{pChnlCode}) AND EXISTS (SELECT ProdCode FROM shopion.tPrfCompStoreProd WHERE ProdCode = P.ProdCode AND CompCode = #{pCompCode}) GROUP BY P.ProdCode, P.ShopProdCode, P.BrandName, P.ModelName, P.SalePrice, P.VatRate, P.MakerName, P.OriginName, P.DeliFeeType, P.DeliFeeAmt, P.SaleYn, P.RegistDate, P.ChangeDate
ORDER BY P.RegistDate DESC ORDER BY COUNT(*) DESC ORDER BY SUM(OP.ProdQty) DESC
LIMIT #{topCnt}, #{countPerPage}

SELECT COUNT(*) FROM (
SELECT P.ProdCode
FROM shopion.tPrdProd P
LEFT OUTER JOIN (
    SELECT shopion.tStrProdCpn.*, tStrProdCpnProd.ProdCode, tStrProdCpnProd.ChnlCode
    FROM shopion.tStrProdCpn
    INNER JOIN shopion.tStrProdCpnProd ON shopion.tStrProdCpnProd.CpnId = shopion.tStrProdCpn.CpnId
    AND shopion.tStrProdCpnProd.ChnlCode = #{pChnlCode}
) PC ON P.ProdCode = PC.ProdCode
LEFT OUTER JOIN (
    SELECT shopion.tStrPoint.*, tStrPointProd.ProdCode, tStrPointProd.ChnlCode
    FROM shopion.tStrPoint
    INNER JOIN shopion.tStrPointProd ON shopion.tStrPointProd.PointId = shopion.tStrPoint.PointId
    AND shopion.tStrPointProd.ChnlCode = #{pChnlCode}
) PP ON P.ProdCode = PP.ProdCode

LEFT OUTER JOIN shopion.tOrdOrderProd OP ON OP.ProdCode = P.ProdCode
LEFT OUTER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo AND O.CustId = #{pCustId}
INNER JOIN shopion.tPrfCustConcrnProd CCP ON CCP.ProdCode = P.ProdCode AND CCP.CustId = #{pCustId}


INNER JOIN shopion.tOrdOrderProd OP ON OP.ProdCode = P.ProdCode
INNER JOIN shopion.tOrdOrder O ON O.OrderNo = OP.OrderNo AND O.CustId = #{pCustId}

WHERE P.SaleYn = 1
AND EXISTS (SELECT ProdCode FROM shopion.tPrdProdChnl WHERE ProdCode = P.ProdCode AND ChnlCode = #{pChnlCode})
AND EXISTS (SELECT ProdCode FROM shopion.tPrfCompStoreProd WHERE ProdCode = P.ProdCode AND CompCode = #{pCompCode})
GROUP BY P.ProdCode, P.ShopProdCode, P.BrandName, P.ModelName, P.SalePrice, P.VatRate, P.MakerName, P.OriginName, P.DeliFeeType, P.DeliFeeAmt, P.SaleYn, P.RegistDate, P.ChangeDate
) T_COUNT

SELECT CP.*
FROM shopion.tPrfCustConcrnProd CP
INNER JOIN shopion.tPrdProd P ON CP.ProdCode = P.ProdCode
WHERE CP.CustId = #{custId}
AND CP.ProdCode = #{prodCode}
AND P.SaleYn = 1

mapper.insert:
INSERT INTO shopion.tPrfCustConcrnProd (
    CustId, ProdCode, ChnlCode, State, Remark, RegistDate, RegistId, RegistName
) VALUES (
    #{custId}, #{prodCode}, #{chnlCode}, #{state}, #{remark}, NOW(), #{registId}, #{registName}
)

mapper.update:
UPDATE shopion.tPrfCustConcrnProd SET
    State = #{state}, Remark = #{remark},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE CustId = #{custId}
AND ProdCode = #{prodCode}

mapper.delete:
DELETE FROM shopion.tPrfCustConcrnProd
WHERE CustId = #{custId}
AND ProdCode = #{prodCode}
